import {materials} from '../../core/index.js';
import {FACE} from '../../modeling/parts.js';
import {THREE,roundedRect,mesh,hole,solid,ring,box,cylinder} from './geometry.js';
import {spec} from './dimensions.js';
function outline(){const s=new THREE.Shape();s.moveTo(-8,-24);s.lineTo(-5.3,-24);s.lineTo(-5.3,-16);s.lineTo(5.3,-16);s.lineTo(5.3,-24);s.lineTo(8,-24);s.absarc(8,-20,4,-Math.PI/2,0,false);s.lineTo(12,20);s.absarc(8,20,4,0,Math.PI/2,false);s.lineTo(-8,24);s.absarc(-8,20,4,Math.PI/2,Math.PI,false);s.lineTo(-12,-20);s.absarc(-8,-20,4,Math.PI,Math.PI*1.5,false);s.closePath();return s;}
function leftWall(){const s=new THREE.Shape();s.moveTo(-8,24);s.absarc(-8,20,4,Math.PI/2,Math.PI,false);s.lineTo(-12,-20);s.absarc(-8,-20,4,Math.PI,Math.PI*1.5,false);s.lineTo(-5.3,-24);s.lineTo(-5.3,-22.8);s.lineTo(-8,-22.8);s.absarc(-8,-20,2.8,-Math.PI/2,-Math.PI,true);s.lineTo(-10.8,20);s.absarc(-8,20,2.8,Math.PI,Math.PI/2,true);s.lineTo(-8,24);s.closePath();return s;}
function m5(parent,mat){const frame=new THREE.Group();frame.name='Original U041 unpainted physical M5 moulding';frame.position.set(0,-19.2,-3.92);frame.quaternion.copy(FACE.back);parent.add(frame);const glyphs=[];for(const[name,points]of[['M',[[-4.5,-2],[-4.5,2],[-4,2],[-2.5,.25],[-1,2],[-.5,2],[-.5,-2],[-1,-2],[-1,1.15],[-2.5,-.5],[-4,1.15],[-4,-2]]],['5',[[.4,2],[4.4,2],[4.4,1.5],[.95,1.5],[.95,.35],[3.2,.35],[4.1,-.15],[4.4,-.7],[4.4,-1.4],[3.95,-2],[.4,-2],[.4,-1.5],[3.7,-1.5],[3.9,-1.1],[3.9,-.8],[3.65,-.35],[3.1,-.15],[.4,-.15]]]])glyphs.push(mesh(frame,solid(new THREE.Shape(points.map(p=>new THREE.Vector2(...p))),.08),mat,[0,0,0],'PbHub actual white '+name+' relief'));return{frame,glyphs};}
export function casing(host){const white=materials.plastic(0xeceee8,{roughness:.81}),rearShape=roundedRect(24,48,4);for(const[x,y]of spec.mounting.centres)hole(rearShape,x,y,2.5);hole(rearShape,0,-12,1.65);
 const rear=mesh(host.body,solid(rearShape,1),white,[0,0,-3.92],'PbHub original closed rear skin with two true bores and screw opening'),frontShape=outline();frontShape.holes.push(roundedRect(20.6,30.2,.8,{cx:0,cy:7.6,path:new THREE.Path()}));for(const[x,y]of spec.mounting.centres)hole(frontShape,x,y,2.5);const front=mesh(host.body,solid(frontShape,1),white,[0,0,3],'PbHub original real open front frame and input boundary notch'),left=leftWall(),right=new THREE.Shape(left.getPoints(64).map(p=>new THREE.Vector2(-p.x,p.y))),sides=[];for(const[s,name]of[[left,'left'],[right,'right']])sides.push(mesh(host.body,solid(s,5.92),white,[0,0,-2.92],'PbHub original '+name+' real perimeter wall'));
 const top=box(host.body,[16,1.2,5.92],[0,23.4,.04],white,'PbHub original closed upper end'),lowerFloor=box(host.body,[10.6,1.2,1.6],[0,-23.4,-2.12],white,'PbHub original lower bridge supports input floor'),bosses=[];for(const[x,y]of spec.mounting.centres)bosses.push(mesh(host.body,ring(3.3,2.5,5.92),white,[x,y,-2.92],'PbHub true open mounting sleeve'));const screwBoss=mesh(host.body,ring(2,.8,5.92),white,[0,-12,-2.92],'PbHub fixed screw support sleeve'),posts=[];for(const x of[-7.7,7.7])for(const y of[-5.6,20.2])posts.push(mesh(host.body,cylinder(.9,2.92),white,[x,y,-1.46],'PbHub inferred rear-toPCB physical support'));
 return{rear,front,sides,top,lowerFloor,bosses,screwBoss,posts,relief:m5(host.body,white)};
}
export function fixing(host){const metal=materials.metal(0xadb2aa,{roughness:.4}),s=new THREE.Shape();s.absarc(0,0,1.45,0,Math.PI*2,false);const pts=[[-.22,-.85],[.22,-.85],[.22,-.22],[.85,-.22],[.85,.22],[.22,.22],[.22,.85],[-.22,.85],[-.22,.22],[-.85,.22],[-.85,-.22],[-.22,-.22]];s.holes.push(new THREE.Path(pts.map(v=>new THREE.Vector2(...v))));const head=mesh(host.body,solid(s,.48),metal,[0,-12,-3.9],'PbHub actual fixed rear screw with inferred cruciform recess'),floor=mesh(host.body,cylinder(.9,.08),materials.plastic(0x42483e),[0,-12,-3.46],'PbHub genuine recessed screw-drive floor'),washer=mesh(host.body,ring(1.65,.7,.3),metal,[0,-12,-3.42],'PbHub actual rear screw bearing'),shaft=mesh(host.body,cylinder(.7,5.7),metal,[0,-12,-.27],'PbHub fixed screw shaft');return{head,floor,washer,shaft};}
